{
  const B=window.BYJHCopy||{t:(_key,fallback,values={})=>fallback.replace(/\{([A-Za-z_][\w]*)\}/g,(match,key)=>key in values?String(values[key]):match),h(key,fallback,values){return this.t(key,fallback,values).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}};
(async()=>{

  const {esc,icon,api,field,textarea,select,handleForm}=W;
  const C=(key,fallback)=>(window.BYJH_COPY||{})[key]??fallback;
  const E=(key,fallback)=>esc(C(key,fallback));
  const L=(key,fallback)=>E(key,fallback).replace(/\n/g,'<br>');
  const root=document.querySelector('#app'),params=new URLSearchParams(location.search);
  const apply=location.pathname.startsWith('/apply'),admin=location.pathname.startsWith('/admin');
  const role=admin?'admin':location.pathname.startsWith('/partners')||params.get('role')==='partner'?'partner':'member';
  const session=await api('session');
  if(!apply&&session.user&&session.user.role===role){location.replace(role==='admin'?'/admin/':'/account/');return;}
  const setup=admin&&session.needsSetup;
  const title=setup?`${B.h("ui.access.44f8ed00b3","YOUR")}<br><span>${B.h("ui.access.562eb1dd73","PRIVATE OFFICE.")}</span>`:admin?`${B.h("ui.access.b521caa6e1","ADMIN")}<br><span>${B.h("ui.access.d24a52a590","ACCESS.")}</span>`:`${E(role+(apply?'.apply.first':'.login.first'),apply?B.t("ui.access.24b61d9aa8","BECOME A"):role.toUpperCase())}<br><span>${E(role+(apply?'.apply.second':'.login.second'),apply?role.toUpperCase()+'.':B.t("ui.access.d24a52a590","ACCESS."))}</span>`;
  const subtitle=setup?B.h("ui.access.9fa6ecbd46","Create the owner account for your local BYJH workspace."):admin?B.h("ui.access.e7892b0be2","Sign in to your private office. Every detail, taken care of."):E(role+(apply?'.apply.description':'.login.description'),'');
  root.innerHTML=`<div class="auth-layout"><section class="auth-left"><a class="auth-brand" href="/" target="_top"><img src="/assets/byjh/logo-dark.png" alt="${B.h("ui.access.d09d7b5217","BYJH")}"><span>${L('brand','BESPOKE LIFESTYLE\nMANAGEMENT')}</span></a><div class="auth-box"><div class="eyebrow-w">${setup?B.h("ui.access.ebe3bf167b","WELCOME TO BYJH"):apply?B.h("ui.access.applicationEyebrow","{role} APPLICATION",{role:W.label('role',role)}):role==='admin'?B.h("ui.access.b3994ed4a1","THE PRIVATE OFFICE"):B.h("ui.access.accessEyebrow","{role} ACCESS",{role:W.label('role',role)})}</div><h1>${title}</h1><p class="sub">${subtitle}</p>${!admin&&!apply?`<nav class="portal-tabs" aria-label="${B.h("ui.access.144b49b7c5","Account type")}"><a class="${role==='member'?'active':''}" href="/members/login/">${B.h("ui.access.1cb449c112","Members")}</a><a class="${role==='partner'?'active':''}" href="/partners/login/">${B.h("ui.access.aa16f0e59d","Partners")}</a></nav>`:''}<form id="auth-form">${setup||apply?field('name',C('form.name',"Full name"),'','text',true,'autocomplete="name" maxlength="120"'):''}${apply&&role==='partner'?field('company',C('form.company',"Company name"),'','text',true,'autocomplete="organization" maxlength="160"'):''}${field('email',C('form.email',"Email address"),'','email',true,'autocomplete="email" maxlength="254"')}${apply?field('phone',C('form.phone',"Phone number (optional)"),'','tel',false,'autocomplete="tel" maxlength="60"'):''}${apply?select('sector',role==='member'?C('form.memberSector',"Your interests"):C('form.partnerSector',"Business sector"),role==='member'?['Chauffeur services','Lifestyle & concierge','Events & touring','Custom builds','Other']:['Hospitality','Travel & transport','Sport','Fashion & lifestyle','Events','Other'],role==='member'?'Chauffeur services':'Hospitality'):''}${apply&&role==='partner'?field('website',C('form.website',"Business website (optional)"),'','url',false,`placeholder="${B.h("ui.access.a9a13761cc","https://")}" maxlength="300"`):''}${apply?textarea('message',role==='member'?C('form.memberMessage',"What would you like us to know? (optional)"):C('form.partnerMessage',"Tell us about your business (optional)"),'','maxlength="4000"'):''}<div class="field"><label for="auth-password">${setup||apply?E('form.createPassword','Create a password'):E('form.password','Password')}</label><div class="password-wrap"><input id="auth-password" name="password" type="password" required ${setup||apply?'minlength="12"':''} maxlength="128" autocomplete="${setup||apply?'new-password':'current-password'}"><button class="password-toggle" type="button" aria-label="${B.h("ui.access.044b852f30","Show password")}">${B.h("ui.access.d97d1ee339","Show")}</button></div>${setup||apply?`<small>${E('form.passwordHint','At least 12 characters. You’ll use this to access your account.')}</small>`:''}</div>${apply?`<label class="consent"><input name="consent" type="checkbox" required><span>${E('form.consent','I agree that BYJH can use these details to review my application and manage my account.')}</span></label>`:''}<button class="btn primary" type="submit">${setup?B.h("ui.access.137bd6ea96","Create admin account"):apply?E('form.submit','Submit application'):E('form.signin','Sign in')} ${icon('arrow')}</button></form>${apply?`<p class="auth-small">${E('form.already','Already part of our world?')} <a href="/${role}s/login/" target="_top">${E('form.signin','Sign in')}</a></p>`:!admin?`<p class="auth-small">${role==='member'?B.h("ui.access.notMember","Not yet a member?"):B.h("ui.access.notPartner","Not yet a partner?")} <a href="/apply/?role=${role}">${E('form.apply',"Apply to join")}</a></p><p class="auth-small">${E('form.help','Need help signing in?')} <a href="/contact/">${E('form.contact',"Contact the team")}</a></p>`:setup?`<p class="auth-small">${B.h("ui.access.319137ca1e","This account will manage the website, members and partners.")}</p>`:''}</div><div class="auth-foot"><a href="/" target="_top">${E('back',"← Back to BYJH")}</a><span>${E('tagline',"Discreet. Personal. Considered.")}</span></div></section><aside class="auth-image"><img src="/assets/byjh/anniversary-cabin.jpg" alt="${E('quote.alt','A beautifully appointed BYJH private cabin')}"><div class="auth-quote"><div class="eyebrow-w">${E('quote.eyebrow',"THE ART OF EVERY JOURNEY")}</div><h2>${E('quote.first',"OUR FLEET.")}<br><span>${E('quote.second',"YOUR WORLD.")}</span></h2><p>${L('quote.body','Bespoke lifestyle management.\nEvery journey. BYJH.')}</p></div></aside></div>`;
  if(admin){adminCodeSignIn();return;}
  if(params.has('embedded'))document.body.classList.add('embedded-application');
  document.querySelector('.password-toggle').onclick=e=>{const p=document.querySelector('#auth-password');p.type=p.type==='password'?'text':'password';e.target.textContent=p.type==='password'?B.t("ui.access.d97d1ee339","Show"):B.t("ui.access.34d8b60fe2","Hide");e.target.setAttribute('aria-label',p.type==='password'?B.t('ui.access.044b852f30','Show password'):B.t("ui.access.hidePassword","Hide password"));};
  // Admins sign in with a 6-digit code emailed to them instead of a password.
  function adminCodeSignIn(){
    let remembered='';try{remembered=localStorage.getItem('byjh-admin-email')||'';}catch{}
    document.querySelector('#auth-form').outerHTML=`<form id="email-form">${field('email',C('form.email',"Email address"),remembered,'email',true,'autocomplete="email" maxlength="254"')}<button class="btn primary" type="submit">${B.h("ui.access.sendCode","Send verification code")} ${icon('arrow')}</button></form><form id="code-form" hidden><p class="message" id="code-sent" role="status"></p>${field('code',B.t("ui.access.codeLabel","6-digit code"),'','text',true,'inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"')}<button class="btn primary" type="submit">${B.h("ui.access.verifyCode","Verify and sign in")} ${icon('arrow')}</button><p class="auth-small"><a href="#" id="resend-code">${B.h("ui.access.resendCode","Send a new code")}</a> · <a href="#" id="change-email">${B.h("ui.access.changeEmail","Use a different email")}</a></p></form>`;
    const emailForm=document.querySelector('#email-form'),codeForm=document.querySelector('#code-form');
    const submit=(form,busy,callback)=>form.addEventListener('submit',async e=>{
      e.preventDefault();const button=form.querySelector('[type=submit]'),old=button.innerHTML;if(button.disabled)return;
      form.querySelector('[data-error]')?.remove();button.disabled=true;button.textContent=busy;
      try{await callback(Object.fromEntries(new FormData(form)));}catch(err){W.errorBox(form,err.message);}finally{button.disabled=false;button.innerHTML=old;}
    });
    let email='';
    const send=async()=>{
      await api('login/send',{email});
      try{localStorage.setItem('byjh-admin-email',email);}catch{}
      document.querySelector('#code-sent').textContent=B.t("ui.access.codeSent","We’ve emailed a 6-digit code to {email}. It expires in 10 minutes.",{email});
      emailForm.hidden=true;codeForm.hidden=false;codeForm.querySelector('[data-error]')?.remove();codeForm.reset();codeForm.querySelector('#f-code').focus();
    };
    submit(emailForm,B.t("ui.access.sendingCode","Sending…"),async data=>{email=data.email.trim();await send();});
    submit(codeForm,B.t("ui.access.checkingCode","Checking…"),async data=>{await api('login/verify',{code:data.code});window.top.location.href='/admin/';});
    document.querySelector('#resend-code').onclick=async e=>{e.preventDefault();codeForm.querySelector('[data-error]')?.remove();try{await send();W.toast(B.t("ui.access.codeResent","A new code is on its way."));}catch(err){W.errorBox(codeForm,err.message);}};
    document.querySelector('#change-email').onclick=e=>{e.preventDefault();codeForm.hidden=true;emailForm.hidden=false;emailForm.querySelector('#f-email').focus();};
  }
  handleForm(document.querySelector('form'),async data=>{data.role=role;if(apply)data.consent=true;await api(setup?'setup':apply?'apply':'login',data);window.top.location.href=role==='admin'?'/admin/':'/account/'+(apply?'?submitted=1':'');});
})().catch(e=>{document.querySelector('#app').innerHTML=`<p style="padding:40px">${B.h("ui.access.afa5ebf8ae","Unable to connect to the local workspace. Please reload the page.")}</p>`;});

}
